161: # A finding's location keys ("path:line"; "path:" without a line) for the unique-findings measure.
162: # (wave 26b, D7 / F22-7) The path is normalised before it is compared: '\' -> '/', runs of '/'
163: # collapsed, every leading './' dropped, and on Windows (a case-insensitive file system)
164: # lowercased; the line stays exact. Keys are compared ordinally.
165: function ConvertTo-LocationPath {
166:     param([string]$Path)
167:     $p = ([string]$Path).Trim().Replace('\', '/')
168:     $p = [regex]::Replace($p, '/{2,}', '/')
169:     while ($p.StartsWith('./')) { $p = $p.Substring(2) }
170:     if ([IO.Path]::DirectorySeparatorChar -eq [char]'\') { $p = $p.ToLowerInvariant() }
171:     return $p
172: }
173: 
174: function Get-LocationKeys {
175:     param($Finding)
176:     $keys = New-Object System.Collections.Generic.List[string]
177:     foreach ($l in @(Get-PropertyValue $Finding 'locations' @() | Where-Object { $null -ne $_ })) {
178:         $path = ConvertTo-LocationPath ([string](Get-PropertyValue $l 'path' ''))
179:         if (-not $path) { continue }
180:         $line = Get-PropertyValue $l 'line' $null
181:         $keys.Add("$($path):$(if ($null -ne $line) { [string]$line } else { '' })")
182:     }
183:     return , ([string[]]$keys.ToArray())
184: }
