222: # A timestamp field back as text ($null for none): a [datetime] or [DateTimeOffset] that
223: # ConvertFrom-Json made of it (PowerShell 7) returns to the bridge's own form - the local ISO
224: # form of Get-IsoTimestamp, or (-RoundTrip) the UTC round trip of Get-ProcessStartIso.
225: function ConvertTo-DetachedTime {
226:     param($Value, [switch]$RoundTrip)
227:     if ($null -eq $Value -or ($Value -is [string] -and -not $Value)) { return $null }
228:     if ($RoundTrip) { return (ConvertTo-JsonText $Value) }
229:     $at = ConvertTo-WhenOffset $Value
230:     if ($null -eq $at) { return [string]$Value }
231:     return $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant)
232: }
