237: function ConvertTo-DetachedRecord {
238:     param($Record)
239:     if ($Record -is [System.Collections.IDictionary]) { $Record = [pscustomobject]$Record }
240:     $members = New-Object System.Collections.Generic.List[object]
241:     foreach ($m in @(Get-PropertyValue $Record 'members' @())) {
242:         if ($null -eq $m) { continue }
243:         $nValue = $null
244:         $nParsed = 0
245:         if ([int]::TryParse([string](Get-PropertyValue $m 'n' ''), [ref]$nParsed)) { $nValue = $nParsed }
246:         $members.Add((New-DetachedMember -Position ([int](Get-PropertyValue $m 'position' 0)) -Lineage ([string](Get-PropertyValue $m 'lineage' '')) -State ([string](Get-PropertyValue $m 'state' 'pending')) -Outcome ([string](Get-PropertyValue $m 'outcome' '')) -Wall (Get-PropertyValue $m 'wall_seconds' $null) -N $nValue -Handoff ([string](Get-PropertyValue $m 'handoff' '')) -Reply ([string](Get-PropertyValue $m 'reply' ''))))
247:     }
248:     $pidValue = $null
249:     $parsed = 0
250:     if ([int]::TryParse([string](Get-PropertyValue $Record 'pid' ''), [ref]$parsed) -and $parsed -gt 0) { $pidValue = $parsed }
251:     $exitValue = $null
252:     if ([int]::TryParse([string](Get-PropertyValue $Record 'exit' ''), [ref]$parsed)) { $exitValue = $parsed }
253:     $budget = 0
254:     [void][int]::TryParse([string](Get-PropertyValue $Record 'budget_sec' ''), [ref]$budget)
255:     $version = $script:DetachedStatusVersion
256:     if ([int]::TryParse([string](Get-PropertyValue $Record 'status_version' ''), [ref]$parsed)) { $version = $parsed }
257:     return [pscustomobject]@{
258:         status_version = $version
259:         id             = [string](Get-PropertyValue $Record 'id' '')
260:         id8            = [string](Get-PropertyValue $Record 'id8' '')
261:         task           = [string](Get-PropertyValue $Record 'task' '')
262:         kind           = [string](Get-PropertyValue $Record 'kind' 'run')
263:         state          = [string](Get-PropertyValue $Record 'state' '')
264:         exit           = $exitValue
265:         started        = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'started' $null))
266:         updated        = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'updated' $null))
267:         finished       = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'finished' $null))
268:         wall_seconds   = (Get-PropertyValue $Record 'wall_seconds' $null)
269:         pid            = $pidValue
270:         start_time     = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'start_time' $null) -RoundTrip)
271:         host           = [string](Get-PropertyValue $Record 'host' '')
272:         budget_sec     = $budget
273:         purpose        = [string](Get-PropertyValue $Record 'purpose' '')
274:         reply_name     = [string](Get-PropertyValue $Record 'reply_name' '')
275:         brief          = [string](Get-PropertyValue $Record 'brief' '')
276:         members        = [object[]]$members.ToArray()
277:         summary        = [string](Get-PropertyValue $Record 'summary' '')
278:         log            = [string](Get-PropertyValue $Record 'log' '')
279:         args           = $(if ([string](Get-PropertyValue $Record 'args' '')) { [string]$Record.args } else { $null })
280:     }
281: }
