283: # { Exists; Record (canonical); Error }. Absent -> Exists $false. Present but empty,
284: # unparseable, not an object, without an id or with a state other than starting | running |
285: # done -> Error.
286: function Read-DetachedStatus {
287:     param([string]$Path)
288:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return [pscustomobject]@{ Exists = $false; Record = $null; Error = '' } }
289:     $text = Read-SharedText -Path $Path
290:     $obj = $null
291:     $why = ''
292:     if (-not $text.Trim()) { $why = 'it is empty or could not be read' }
293:     else {
294:         try { $obj = ConvertFrom-Json -InputObject $text } catch { $why = "it does not parse: $(ConvertTo-OneLine $_.Exception.Message)" }
295:         if (-not $why -and -not (Test-IsJsonObject $obj)) { $why = 'it is not a JSON object' }
296:         if (-not $why -and -not [string](Get-PropertyValue $obj 'id' '')) { $why = 'it names no id' }
297:         if (-not $why -and @('starting', 'running', 'done') -notcontains [string](Get-PropertyValue $obj 'state' '')) { $why = "its state '$(Get-PropertyValue $obj 'state' '')' is not one of starting|running|done" }
298:     }
299:     if ($why) { return [pscustomobject]@{ Exists = $true; Record = $null; Error = "the status file '$Path' cannot be used: $why" } }
300:     return [pscustomobject]@{ Exists = $true; Record = (ConvertTo-DetachedRecord $obj); Error = '' }
301: }
