303: # Every detached run of a task, newest first (by `started`, else the file time; then by id8):
304: # { Path; Id8; Record; Error; When; Log }. An atomic-write temp is not a run.
305: function Read-DetachedRuns {
306:     param([string]$TaskDir)
307:     $runs = New-Object System.Collections.Generic.List[object]
308:     if (-not $TaskDir -or -not [IO.Directory]::Exists($TaskDir)) { return , ([object[]]@()) }
309:     foreach ($f in [IO.Directory]::GetFiles($TaskDir, '.consult.detached-*.status.json')) {
310:         $name = [IO.Path]::GetFileName($f)
311:         if ($name -notmatch '^\.consult\.detached-([0-9A-Za-z]+)\.status\.json$') { continue }
312:         $id8 = $Matches[1].ToLowerInvariant()
313:         $rd = Read-DetachedStatus -Path $f
314:         $when = $null
315:         if ($rd.Record) { $when = ConvertTo-WhenOffset $rd.Record.started }
316:         if ($null -eq $when) { try { $when = [DateTimeOffset]([IO.File]::GetLastWriteTimeUtc($f)) } catch { $when = [DateTimeOffset]::MinValue } }
317:         $runs.Add([pscustomobject]@{ Path = $f; Id8 = $id8; Record = $rd.Record; Error = $rd.Error; When = $when; Log = (Join-Path $TaskDir ".consult.detached-$id8.log") })
318:     }
319:     $sorted = @($runs | Sort-Object -Property @{ Expression = { $_.When }; Descending = $true }, @{ Expression = { $_.Id8 }; Descending = $false })
320:     return , ([object[]]$sorted)
321: }
