324: function Format-DetachedSpan {
325:     param([TimeSpan]$Span)
326:     if ($Span.TotalSeconds -lt 0) { $Span = [TimeSpan]::Zero }
327:     if ($Span.TotalSeconds -lt 90) { return "$([int][Math]::Floor($Span.TotalSeconds)) s" }
