329:     if ($Span.TotalHours -lt 48) { return ('{0} h {1:D2} min' -f [int][Math]::Floor($Span.TotalHours), $Span.Minutes) }
330:     return ('{0} d {1:D2} h' -f [int][Math]::Floor($Span.TotalDays), $Span.Hours)

