7911: # Kills the process AND its descendants (the launcher is usually a shim: cmd.exe or
7912: # node in front of the real codex binary). Windows: taskkill /T /F; elsewhere: the
7913: # pgrep -P tree. Best effort; returns the pids (root included) still alive after it,
7914: # as an [int[]] (empty when the whole tree is gone).
7915: # A kill returns before the OS has torn the process down: the killed pids are polled
7916: # (100 ms steps, up to 3 s) and only those still alive after that wait are survivors.
7917: # A process merely still exiting must not be recorded as a survivor - that would keep
7918: # .consult.pending.json in state 'survivors' and block the task until a later run.
7919: function Stop-ProcessTree {
7920:     param($Process)
7921:     if ($null -eq $Process) { return , ([int[]]@()) }
7922:     $rootId = $Process.Id
7923:     $descendants = Get-DescendantPids -RootId $rootId
7924:     $previous = $ErrorActionPreference
7925:     $ErrorActionPreference = 'Continue'
7926:     try {
7927:         if ($script:OnWindows) {
7928:             try { & taskkill.exe /PID $rootId /T /F 2>$null | Out-Null } catch { }
7929:         }
7930:         # The root before its descendants: a root that outlives its children reacts to
7931:         # their death (a shell or node shim carries on and may start new processes).
7932:         try { if (-not $Process.HasExited) { $Process.Kill() } } catch { }
7933:         foreach ($d in $descendants) {
7934:             try { Stop-Process -Id $d -Force -ErrorAction SilentlyContinue } catch { }
7935:         }
7936:         try { $null = $Process.WaitForExit(10000) } catch { }
7937:     } finally {
7938:         $ErrorActionPreference = $previous
7939:     }
7940:     # Get-Process by pid is the liveness probe on every platform (kill -0 semantics).
7941:     $deadline = [DateTime]::UtcNow.AddSeconds(3)
7942:     while ($true) {
7943:         $alive = New-Object System.Collections.Generic.List[int]
7944:         $rootGone = $true
7945:         try { $rootGone = $Process.HasExited } catch { $rootGone = $true }
7946:         if (-not $rootGone) { $alive.Add($rootId) }
7947:         foreach ($d in $descendants) {
7948:             if (Get-Process -Id $d -ErrorAction SilentlyContinue) { $alive.Add($d) }
7949:         }
7950:         if ($alive.Count -eq 0 -or [DateTime]::UtcNow -ge $deadline) { break }
7951:         Start-Sleep -Milliseconds 100
7952:     }
7953:     return , ([int[]]$alive.ToArray())
7954: }
